module TopModule (
    input  [6:0] y,
    input        w,
    output       Y1,
    output       Y3
);

    // Next-state logic for Y2 and Y4 based on the state machine
    assign Y1 = (y[1] & ~w) | (y[3] & ~w) | (y[5] & w); // Y2 corresponds to y[1]
    assign Y3 = (y[3] & ~w) | (y[4] & w);               // Y4 corresponds to y[3]

endmodule
